const allItems = $input.all();
const staticData = $getWorkflowStaticData('global');
const seenUrls = staticData['savedUrls'] || [];
const processedItems = [];

for (const item of allItems) {
  const url = item.json.link || item.json.url || item.json.guid || '';
  let textContent = item.json['content:encoded'] || item.json.content || item.json.contentSnippet || item.json.description || item.json.summary || '';
  const title = item.json.title || 'Untitled';
  const pubDate = item.json.pubDate || item.json.isoDate || '';

  if (!url || seenUrls.includes(url)) continue;

  textContent = textContent
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 3000);

  if (textContent.length < 80) continue;

  processedItems.push({ url, title, textContent, pubDate });
}

if (processedItems.length > 0) {
  staticData['savedUrls'] = [...seenUrls, ...processedItems.map(i => i.url)].slice(-500);
}

return [{ json: { articles: processedItems, count: processedItems.length } }];

