parameters.jsCode:
const markdown = $json.output.final_newsletter_markdown || '';
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const subject = `[Signal] ${today} — Top 3 Intelligence Briefings`;

const htmlBody = markdown
  .replace(/^# (.+)$/gm, '<h1 style="color:#e2e8f0;font-size:26px;font-weight:700;margin:0 0 24px 0;">$1</h1>')
  .replace(/^## (.+)$/gm, '<h2 style="color:#a0aec0;font-size:16px;font-weight:600;margin:28px 0 10px 0;text-transform:uppercase;letter-spacing:0.06em;">$1</h2>')
  .replace(/\*\*(.+?)\*\*/g, '<strong style="color:#63b3ed;">$1</strong>')
  .replace(/\n\n/g, '</p><p style="color:#cbd5e0;font-size:15px;line-height:1.7;margin:0 0 14px 0;">')
  .replace(/\n/g, '<br>');

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#1a202c;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;"><div style="max-width:620px;margin:0 auto;padding:32px 20px;"><div style="background:#2d3748;border-radius:8px;padding:36px;border:1px solid #4a5568;"><p style="color:#4a5568;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:0.12em;margin:0 0 20px 0;">DAILY INTELLIGENCE</p>${htmlBody}<div style="margin-top:36px;padding-top:20px;border-top:1px solid #4a5568;"><p style="color:#4a5568;font-size:11px;margin:0;">You subscribed to this briefing. <a href="{{unsubscribe_url}}" style="color:#4a5568;">Unsubscribe</a></p></div></div></div></body></html>`;

return { json: { html, subject, markdown } };

